float drawInventory(Graphics&g,float x,float y,float w,bool hot=false){for(auto&b:bots()){txt(g,"[BOT"+std::to_string(b.value("id",0))+"] "+str(b,"name"),x,y,w,18,theme("Text"),10);y+=19;auto arr=b.value("inventory",J::array());int count=hot?std::min(9,(int)arr.size()):(int)arr.size();float cell=w/9;for(int i=0;i<count;i++){int row=i/9,col=i%9;box(g,x+col*cell,y+row*(cell+2),cell-1,cell,theme(arr[i].value("selected",false)?"Accent":"Field",90),1);drawItem(g,arr[i],x+col*cell+1,y+row*(cell+2)+1,cell-3);}y+=std::ceil(count/9.f)*(cell+2)+8;if(!hot){txt(g,"Armor / Offhand",x,y,w,16,theme("Off Text"),10);y+=17;auto gear=b.value("armor",J::array());gear.push_back(b.value("offhand",J::object()));int i=0;for(auto&a:gear){drawItem(g,a,x+(i++)*25,y,23);}y+=27;}}return y;}
