static std::set<std::string>a={"Config","Friendlist","EnemyList","Activity","PublicChat","PrivateChat","KitNow","WorldNow","TPA","ChatQueue","CustomCommand","Inventory","ClickGUI"};if(a.count(m)){toggleOpen(m);return;}
